from pathlib import Path
from setup_deseq2_reference import ROOT,pin,save
from setup_smr_cmake import linux
from validate_mashr_native import JAVA21
from probe_smr_workflow import BASE,PREFIX,request,analysis


def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--build',required=True,type=Path);p.add_argument('--out',required=True,type=Path);a=p.parse_args();out=a.out.resolve();assert out.is_relative_to(BASE) and not out.exists();out.mkdir(parents=True);build=json.loads((a.build/'COMPLETED.json').read_bytes());jar=ROOT/build['artifact']['path'];assert pin(jar)=={k:build['artifact'][k] for k in ['bytes','sha256']};pins={n:pin(ROOT/n) for n in [*build['source_pins'],'tools/literature/probe_smr_workflow.py',Path(__file__).resolve().relative_to(ROOT).as_posix()]};assert all(pins[n]==v for n,v in build['source_pins'].items());runner=out/'SmrQfileBoundaries.java';runner.write_text('''package org.jlinalg.cli;import java.nio.file.*;import static org.jlinalg.cli.Monocle3WorkflowRequest.*;
public final class SmrQfileBoundaries{public static void main(String[] args)throws Exception{Path home=Path.of(args[0]);var r=SmrWorkflowRequest.parse(object(NextflowParameters.parse(Files.readString(home.resolve("request.json")),1048576,100000)),home);var budget=new SmrWorkflowInputs.Budget(r.nativeOperations());var expected=SmrWorkflowInputs.qfile(home.resolve("qtl.qfile"),home.resolve("native-quantization.tsv"),r,budget);var actual=SmrWorkflowBesd.read(home.resolve("original"),r,budget);int differences=SmrWorkflowInputs.preparation(expected,actual,home.resolve("complete-native-comparison.tsv"),budget);System.out.println("PASS8 complete source branch controls; explicit1ULP differences="+differences);}}
''',encoding='utf8',newline='\n');classes=out/'classes';classes.mkdir();command=[str(JAVA21/'javac.exe'),'--release','17','-Xlint:all','-Werror','-encoding','UTF-8','-cp',str(jar),'-d',str(classes),str(runner)];r=subprocess.run(command,cwd=ROOT,capture_output=True,timeout=120);(out/'compile.stdout').write_bytes(r.stdout);(out/'compile.stderr').write_bytes(r.stderr);assert r.returncode==0,r.stderr.decode(errors='replace');reports=[]
    for version in ['1.3.1','1.4.3']:
        home=out/version;home.mkdir();values=['NA','0','1','1e-151','1e-150','1e-6','.5',repr(math.nextafter(1,0))];rows=['SNP Chr BP A1 A2 Freq Probe Probe_Chr Probe_bp Gene Orientation b SE p']
        for i,value in enumerate(values):rows.append(' '.join(map(str,['rsPrep'+str(i+1),1,1000000+i,'A','G',.3,'probe-prep',1,1000000,'GENE_PREP','+',.5+i*.05,.02,value])))
        (home/'qtl.qfile').write_text('\n'.join(rows)+'\n',encoding='ascii');q=request(version,BASE/'synthetic-controls-1',out/'unused',[analysis(version,'unused',method='off')]);q['qtl']['file']=linux(home/'qtl.qfile');save(home/'request.json',q);runtime=BASE/'runtime-profile-2'/version;program=runtime/'bin/smr';before=pin(program);command=PREFIX+['/usr/bin/env','-i','PATH=/usr/bin:/bin','LC_ALL=C','OMP_NUM_THREADS=1',linux(runtime/'lib/ld-linux-x86-64.so.2'),'--inhibit-cache','--library-path',linux(runtime/'lib'),'--inhibit-rpath','',linux(program),'--qfile',linux(home/'qtl.qfile'),'--make-besd','--out',linux(home/'original'),'--thread-num','1'];r=subprocess.run(command,cwd=ROOT,capture_output=True,timeout=120);(home/'original.stdout').write_bytes(r.stdout);(home/'original.stderr').write_bytes(r.stderr);save(home/'original-process.json',dict(command=command,exit_code=r.returncode));assert r.returncode==0 and pin(program)==before;command=[str(JAVA21/'java.exe'),'-cp',os.pathsep.join(map(str,[classes,jar])),'org.jlinalg.cli.SmrQfileBoundaries',str(home)];r=subprocess.run(command,cwd=ROOT,capture_output=True,timeout=120);(home/'native.stdout').write_bytes(r.stdout);(home/'native.stderr').write_bytes(r.stderr);save(home/'native-process.json',dict(command=command,exit_code=r.returncode));reports.append(dict(version=version,exit_code=r.returncode,cases=8,original_program=before,complete_original_files={f.name:pin(f) for f in home.glob('original.*')}));print(version,'native exit',r.returncode,flush=True)
    assert all(pin(ROOT/n)==v for n,v in pins.items());passed=all(r['exit_code']==0 for r in reports);save(out/'COMPLETED.json',dict(status='passed-complete-original-Qfile-SE-branch-boundaries' if passed else 'FAIL2_ORIGINAL_QFILE_SE_BOUNDARY_MISMATCH',artifact=build['artifact'],source_pins=pins,versions=reports,original_preparation_cases=16,original_scientific_source_patched=False,adapter_admitted=False,implementation_credit=False,whole_goal_complete=False));return 0 if passed else 2


